List_String* List_String_make(void) {
List_String* list = (List_String*)SPITE_MALLOC(sizeof(List_String));
list->header.ref_count = 1;
list->header.class_id = 98;
#ifdef SPITE_DEBUG_MEMORY
spite_debug_register_object(list, 98);
#endif
list->items = 0;
list->count = 0;
list->capacity = 0;
return list;
}
List_String* List_String_retain(List_String* self) {
if (self != 0) self->header.ref_count = self->header.ref_count + 1;
return self;
}
void List_String_release(List_String* self) {
if (self == 0) return;
self->header.ref_count = self->header.ref_count - 1;
if (self->header.ref_count > 0) return;
for (int64_t spite_index = 0; spite_index < self->count; spite_index = spite_index + 1) { SpiteString_release(self->items[spite_index]); }
SPITE_FREE(self->items);
SPITE_FREE(self);
}
void List_String_add(List_String* self, SpiteString* value) {
if (self->count == self->capacity) {
int64_t new_capacity = self->capacity == 0 ? 4 : self->capacity * 2;
self->items = (SpiteString**)SPITE_REALLOC(self->items, (size_t)new_capacity * sizeof(SpiteString*));
self->capacity = new_capacity;
}
self->items[self->count] = value;
self->count = self->count + 1;
}
int64_t List_String_count(List_String* self) {
return self->count;
}
SpiteString* List_String_get(List_String* self, int64_t index) {
if (index < 0 || index >= self->count) {
return (&spite_static_string_empty);
}
return SpiteString_retain(self->items[index]);
}
void List_String_set(List_String* self, int64_t index, SpiteString* value) {
if (index < 0 || index >= self->count) { SpiteString_release(value); return; }
SpiteString_release(self->items[index]);
self->items[index] = value;
}
void List_String_insert(List_String* self, int64_t index, SpiteString* value) {
int64_t clamped_index = index < 0 ? 0 : (index > self->count ? self->count : index);
if (self->count == self->capacity) {
int64_t new_capacity = self->capacity == 0 ? 4 : self->capacity * 2;
self->items = (SpiteString**)SPITE_REALLOC(self->items, (size_t)new_capacity * sizeof(SpiteString*));
self->capacity = new_capacity;
}
for (int64_t spite_index = self->count; spite_index > clamped_index; spite_index = spite_index - 1) { self->items[spite_index] = self->items[spite_index - 1]; }
self->items[clamped_index] = value;
self->count = self->count + 1;
}
void List_String_prepend(List_String* self, SpiteString* value) {
List_String_insert(self, 0, value);
}
void List_String_remove_at(List_String* self, int64_t index) {
if (index < 0 || index >= self->count) return;
SpiteString_release(self->items[index]);
for (int64_t spite_index = index; spite_index < self->count - 1; spite_index = spite_index + 1) { self->items[spite_index] = self->items[spite_index + 1]; }
self->count = self->count - 1;
}
SpiteString* List_String_pop(List_String* self) {
if (self->count == 0) return (&spite_static_string_empty);
SpiteString* value = self->items[self->count - 1];
self->count = self->count - 1;
return value;
}
SpiteString* List_String_remove_first(List_String* self) {
if (self->count == 0) return (&spite_static_string_empty);
SpiteString* value = self->items[0];
int64_t index = 0;
for (int64_t spite_index = index; spite_index < self->count - 1; spite_index = spite_index + 1) { self->items[spite_index] = self->items[spite_index + 1]; }
self->count = self->count - 1;
return value;
}
SpiteString* List_String_first(List_String* self) {
if (self->count == 0) return (&spite_static_string_empty);
return SpiteString_retain(self->items[0]);
}
SpiteString* List_String_last(List_String* self) {
if (self->count == 0) return (&spite_static_string_empty);
return SpiteString_retain(self->items[self->count - 1]);
}
bool List_String_is_empty(List_String* self) {
return self->count == 0;
}
void List_String_clear(List_String* self) {
for (int64_t spite_index = 0; spite_index < self->count; spite_index = spite_index + 1) { SpiteString_release(self->items[spite_index]); }
self->count = 0;
}
void List_String_reverse(List_String* self) {
for (int64_t spite_index = 0; spite_index < self->count / 2; spite_index = spite_index + 1) {
SpiteString* spite_swap_temporary = self->items[spite_index];
self->items[spite_index] = self->items[self->count - 1 - spite_index];
self->items[self->count - 1 - spite_index] = spite_swap_temporary;
}
}
bool List_String_contains(List_String* self, SpiteString* value) {
for (int64_t spite_index = 0; spite_index < self->count; spite_index = spite_index + 1) {
if (SpiteString_equals(self->items[spite_index], value)) return true;
}
return false;
}
List_String* SpiteString_split(SpiteString* self, SpiteString* separator) {
List_String* result = List_String_make();
if (separator->length == 0) {
for (int64_t index = 0; index < self->length; index = index + 1) { List_String_add(result, SpiteString_character_at(self, index)); }
return result;
}
int64_t piece_start = 0;
int64_t index = 0;
while (index <= self->length - separator->length) {
if (memcmp(self->data + index, separator->data, (size_t)separator->length) == 0) {
List_String_add(result, SpiteString_slice(self, piece_start, index));
index = index + separator->length;
piece_start = index;
} else {
index = index + 1;
}
}
List_String_add(result, SpiteString_slice(self, piece_start, self->length));
return result;
}
List_String* SpiteString_lines(SpiteString* self) {
SpiteString* spite_newline = spite_string_from_cstring_owned("\n");
List_String* result = SpiteString_split(self, spite_newline);
SpiteString_release(spite_newline);
return result;
}
SpiteString* List_String_join(List_String* self, SpiteString* separator) {
SpiteString* result = (&spite_static_string_empty);
for (int64_t index = 0; index < self->count; index = index + 1) {
SpiteString* next = index == 0 ? spite_string_from_bytes(self->items[index]->data, self->items[index]->length) : SpiteString_concat(result, self->items[index]);
SpiteString_release(result);
result = next;
if (index + 1 != self->count) {
SpiteString* with_separator = SpiteString_concat(result, separator);
SpiteString_release(result);
result = with_separator;
}
}
return result;
}
int64_t SpiteArguments_count(SpiteArguments* self) {
    return self->count;
}

SpiteString* SpiteArguments_get(SpiteArguments* self, int64_t index) {
    if (index < 0 || index >= self->count) return (&spite_static_string_empty);
    return spite_string_from_cstring_owned(self->items[index]);
}

SpiteString* SpiteArguments_lookup(SpiteArguments* self, const char* key) {
    int64_t key_length = (int64_t)strlen(key);
    for (int64_t index = 0; index < self->count; index = index + 1) {
        const char* item = self->items[index];
        if (strncmp(item, "--", 2) == 0 && strncmp(item + 2, key, (size_t)key_length) == 0 && item[2 + key_length] == '=') {
            return spite_string_from_cstring_owned(item + 2 + key_length + 1);
        }
    }
    return 0;
}

